var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return H.flag("U_INTERCESSOR_SQUAD_A", "sm11e_point_blank")

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
var cq = load("res://scripts/rules/shootingtypes/CloseQuartersShooting.gd").new()
var u = H.unit("U_INTERCESSOR_SQUAD_A")
var rifle = {}
var blast = {}
for w in u.meta.weapons:
	if str(w.name).begins_with("Bolt Rifle") and rifle.is_empty():
		rifle = w
	if "blast" in str(w.get("special_rules", "")).to_lower() and blast.is_empty():
		blast = w
return cq.weapon_allowed(rifle, u, GameState.state).allowed and not cq.weapon_allowed(blast, u, GameState.state).allowed

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
var w = RulesEngine.get_eligible_targets("U_INTERCESSOR_SQUAD_A", GameState.state).get("U_GRETCHIN_C", {}).get("weapons_in_range", [])
return w.any(func(x): return str(x).begins_with("bolt_rifle"))

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
var ph = H.phase()
var mids = []
for m in H.unit("U_INTERCESSOR_SQUAD_A").models:
	mids.append(str(m.id))
var r = ph.execute_action({"type": "ASSIGN_TARGET", "actor_unit_id": "U_INTERCESSOR_SQUAD_A", "player": 1, "payload": {"weapon_id": "bolt_rifle___focused_fire_ranged", "target_unit_id": "U_GRETCHIN_C", "model_ids": mids}})
if not r.get("success", false):
	return "assign: " + str(r.get("errors", r.get("error", "")))
r = ph.execute_action({"type": "CONFIRM_TARGETS", "player": 1})
return true if r.get("success", false) else "confirm: " + str(r.get("errors", r.get("error", "")))

var main = tree.current_scene
